-- Hand-written, not generated by `prisma migrate dev`'s auto-diff.
-- Service.category is required with no default, and Service already has
-- rows, so the auto-diff would refuse (same situation as add_user_phone).
-- Add nullable, backfill, then enforce NOT NULL.

-- CreateEnum
CREATE TYPE "ServiceType" AS ENUM ('HANDS', 'FEET', 'WAX');

-- Step 1: add as nullable so existing rows aren't rejected.
ALTER TABLE "Service" ADD COLUMN "category" "ServiceType";

-- Step 2: backfill from the service name. At the time of writing the only
-- rows are "Manicure" and "Pedicure"; anything else falls back to HANDS and
-- can be corrected from the admin Services page.
UPDATE "Service" SET "category" = CASE
    WHEN "name" ILIKE '%pedi%' OR "name" ILIKE '%foot%' OR "name" ILIKE '%feet%' THEN 'FEET'::"ServiceType"
    WHEN "name" ILIKE '%wax%' THEN 'WAX'::"ServiceType"
    ELSE 'HANDS'::"ServiceType"
END
WHERE "category" IS NULL;

-- Step 3: now safe to enforce NOT NULL.
ALTER TABLE "Service" ALTER COLUMN "category" SET NOT NULL;
